{"day_uuid": "2d0a1fb1-f501-f779-6a85-304f53fc43d9", "day_number": 6, "day_title": "Sightseeing & Jaisalmer Desert", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Jaisalmer, the \"Golden City,\" charms visitors with its golden sandstone architecture and desert landscapes. Famous for its fort, Jain temples, and camel safaris, it offers a unique blend of history, culture, and adventure in Rajasthan, India.\nAfter breakfast, explore the enchanting Golden City of Rajasthan:\nLater, experience a unique night in tents at the sand dunes desert, complete with cultural programs, camel rides, bonfire, sunset views, and dinner.\nOvernight stay at the Desert Camp.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaisalmer", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "11bc9d08-cad5-5472-599f-5fa892cddc82", "sort_order": 0, "title": "Jaisalmer Fort & Palaces", "description": "A famous fort guarding ancient tales.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "1def8e33-2f26-7c12-f168-1843ac5f5238", "sort_order": 1, "title": "Jain Temples", "description": "Intricate artistry in spiritual reserves.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "1eba2bae-da9f-ca1e-3a04-6cbd988e942f", "sort_order": 2, "title": "Patwon ki Haveli", "description": "Sandstone luxury in desert.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "4dddbeee-e5db-94fc-5cae-4daa6f8a67a7", "sort_